# situ capability map v1
# schema: tiff.situ
# core:   offset size align repr atomic
#
# Core axes are always shown. Any other axis appears only where it has
# been weakened below its strongest value.
#
# Offsets are byte values, or byte:bit where a field does not start on
# a byte boundary. Sizes are bytes unless suffixed with `bit`.

struct tiff_header size=8 repr=ConditionallyConverted(byte_order) canonical=CanonicalGiven(byte_order)
  tiff_header.byte_order                 offset=AbsoluteStatic(0x00) size=Fixed(2) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
  tiff_header.magic                      offset=AbsoluteStatic(0x02) size=Fixed(2) align=Aligned(2) repr=ConditionallyConverted(byte_order) atomic=AtomicWord canonical=CanonicalGiven(byte_order)
  tiff_header.ifd_offset                 offset=AbsoluteStatic(0x04) size=Fixed(4) align=Aligned(4) repr=ConditionallyConverted(byte_order) atomic=AtomicWord canonical=CanonicalGiven(byte_order)
